package xyz.jovanstoiljkovic.isa.dtos.playlist;import xyz.jovanstoiljkovic.isa.dtos.BaseDTO;import xyz.jovanstoiljkovic.isa.dtos.comment.CommentDTOLeaf;import xyz.jovanstoiljkovic.isa.dtos.like.LikeDTOLeaf;import xyz.jovanstoiljkovic.isa.dtos.song.SongDTOLeaf;import xyz.jovanstoiljkovic.isa.dtos.tag.TagDTOLeaf;import xyz.jovanstoiljkovic.isa.dtos.user.UserDTOLeaf;import xyz.jovanstoiljkovic.isa.models.Playlist;import xyz.jovanstoiljkovic.isa.models.Playlist.Visibility;import java.util.List;public class PlaylistDTO extends BaseDTO<Playlist> {    private Long id;    private Visibility visibility;    private UserDTOLeaf user;    private List<SongDTOLeaf> songs;    private List<TagDTOLeaf> tags;    private List<LikeDTOLeaf> likes;    private List<CommentDTOLeaf> comments;    public PlaylistDTO() {    }    public PlaylistDTO(Long id, Visibility visibility) {        this.id = id;        this.visibility = visibility;    }    public PlaylistDTO(Long id, Visibility visibility, UserDTOLeaf user, List<SongDTOLeaf> songs, List<TagDTOLeaf> tags, List<LikeDTOLeaf> likes, List<CommentDTOLeaf> comments) {        this.id = id;        this.visibility = visibility;        this.user = user;        this.songs = songs;        this.tags = tags;        this.likes = likes;        this.comments = comments;    }    public Long getId() {        return id;    }    public void setId(Long id) {        this.id = id;    }    public Visibility getVisibility() {        return visibility;    }    public void setVisibility(Visibility visibility) {        this.visibility = visibility;    }    public UserDTOLeaf getUser() {        return user;    }    public void setUser(UserDTOLeaf user) {        this.user = user;    }    public List<SongDTOLeaf> getSongs() {        return songs;    }    public void setSongs(List<SongDTOLeaf> songs) {        this.songs = songs;    }    public List<TagDTOLeaf> getTags() {        return tags;    }    public void setTags(List<TagDTOLeaf> tags) {        this.tags = tags;    }    public List<LikeDTOLeaf> getLikes() {        return likes;    }    public void setLikes(List<LikeDTOLeaf> likes) {        this.likes = likes;    }    public List<CommentDTOLeaf> getComments() {        return comments;    }    public void setComments(List<CommentDTOLeaf> comments) {        this.comments = comments;    }}